import type {
    OperationalActionType,
    OperationalEventType,
    OperationalTriggerAction,
    OperationalTriggerCondition,
    OperationalTriggerConfig,
    OperationalTriggerScenario,
} from '@/types/operational-triggers';
import { SCHEMA_VERSION } from '@/types/operational-triggers';

export function uid(): string {
    return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 9)}`;
}

export function newCondition(): OperationalTriggerCondition {
    return { id: uid(), field: 'host', operator: 'eq', value: 'celer' };
}

export function newNotifySectorAction(): OperationalTriggerAction {
    return {
        id: uid(),
        type: 'notify_sector',
        target: { sector_slug: 'liquidacao' },
        title: 'Notificação operacional',
        message_template: 'Evento {event_type} para {task_title}{credor}',
        deep_link_template: '',
        origem: 'OPERATIONAL_TRIGGER',
        priority: 3,
    };
}

export function newAction(type: OperationalActionType): OperationalTriggerAction {
    if (type === 'notify_sector') return newNotifySectorAction();
    if (type === 'notify_users') {
        return {
            id: uid(),
            type,
            user_ids: [],
            title: 'Notificação direta',
            message_template: 'Evento operacional',
            priority: 3,
        };
    }
    if (type === 'create_task') {
        return {
            id: uid(),
            type,
            title: 'Tarefa automática',
            message_template: 'Acompanhar {task_title}',
            description_template: 'Criada por gatilho operacional',
            priority: 3,
        };
    }
    if (type === 'webhook') {
        return { id: uid(), type, url: 'https://celer.com.br/webhooks/operational' };
    }
    return { id: uid(), type: 'invalidate_cache', cache_domain: 'operational_triggers' };
}

export function newScenario(index: number, event: OperationalEventType = 'due.liquidacao_ready'): OperationalTriggerScenario {
    return {
        id: uid(),
        name: `Cenário ${index}`,
        enabled: false,
        event,
        logic: 'AND',
        conditions: [],
        actions: [newNotifySectorAction()],
    };
}

export function exportConfig(config: OperationalTriggerConfig) {
    return {
        version: config.version ?? SCHEMA_VERSION,
        is_active: config.is_active ?? true,
        scenarios: config.scenarios ?? [],
    };
}

export function importConfig(json: unknown): OperationalTriggerConfig {
    const data = typeof json === 'string' ? JSON.parse(json) : json;
    if (!data || typeof data !== 'object') {
        throw new Error('JSON inválido');
    }
    const parsed = data as OperationalTriggerConfig;
    if (!Array.isArray(parsed.scenarios)) {
        throw new Error('Campo scenarios ausente');
    }
    return {
        version: parsed.version ?? SCHEMA_VERSION,
        is_active: parsed.is_active ?? true,
        scenarios: parsed.scenarios.map((scenario) => ({
            ...scenario,
            conditions: scenario.conditions ?? [],
            actions: (scenario.actions ?? []).map((action) => ({ ...action })),
        })),
    };
}

export function summarizeImport(config: OperationalTriggerConfig) {
    const enabled = config.scenarios.filter((s) => s.enabled).length;
    const notifyActions = config.scenarios.reduce(
        (acc, scenario) => acc + scenario.actions.filter((a) => a.type === 'notify_sector' || a.type === 'notify_users').length,
        0,
    );
    return {
        totalScenarios: config.scenarios.length,
        enabledScenarios: enabled,
        notifyActions,
    };
}

export function isConfigDirty(local: OperationalTriggerConfig, published: OperationalTriggerConfig | null): boolean {
    if (!published) return true;
    return JSON.stringify(exportConfig(local)) !== JSON.stringify(exportConfig(published));
}

export type ScenarioPublishState = 'synced' | 'dirty' | 'new';

export function getPublishedScenario(
    published: OperationalTriggerConfig | null,
    scenarioId: string,
): OperationalTriggerScenario | undefined {
    return published?.scenarios.find((scenario) => scenario.id === scenarioId);
}

export function getScenarioPublishState(
    draftScenario: OperationalTriggerScenario,
    published: OperationalTriggerConfig | null,
): ScenarioPublishState {
    const publishedScenario = getPublishedScenario(published, draftScenario.id);
    if (!publishedScenario) return 'new';
    return JSON.stringify(draftScenario) === JSON.stringify(publishedScenario) ? 'synced' : 'dirty';
}

export function isScenarioDirty(
    draftScenario: OperationalTriggerScenario,
    published: OperationalTriggerConfig | null,
): boolean {
    return getScenarioPublishState(draftScenario, published) !== 'synced';
}

/** Publishes a single scenario without overwriting unpublished edits in other cards. */
export function buildConfigWithPublishedScenario(
    draft: OperationalTriggerConfig,
    published: OperationalTriggerConfig,
    scenarioId: string,
): OperationalTriggerConfig {
    const draftScenario = draft.scenarios.find((scenario) => scenario.id === scenarioId);
    const scenarios = [...published.scenarios];
    const publishedIndex = scenarios.findIndex((scenario) => scenario.id === scenarioId);

    if (!draftScenario) {
        return {
            version: draft.version ?? published.version ?? SCHEMA_VERSION,
            is_active: draft.is_active ?? published.is_active ?? true,
            scenarios: scenarios.filter((scenario) => scenario.id !== scenarioId),
        };
    }

    if (publishedIndex >= 0) {
        scenarios[publishedIndex] = draftScenario;
    } else {
        scenarios.push(draftScenario);
    }

    return {
        version: draft.version ?? published.version ?? SCHEMA_VERSION,
        is_active: draft.is_active ?? published.is_active ?? true,
        scenarios,
    };
}

