'use client';

import { ArrowRight, Filter, Loader2, Plus, Save, Trash2, Zap } from 'lucide-react';
import { useMemo } from 'react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { COLORS, ProductSelect, TYPOGRAPHY, withAlpha } from '@/design-system';
import { newAction, newCondition, type ScenarioPublishState } from '@/functions/operational-triggers/schema';
import type { OperationalActionType, OperationalTriggerMetadata, OperationalTriggerScenario } from '@/types/operational-triggers';
import { cn } from '@/lib/utils';

import {
    buildScenarioSampleEvent,
    CONDITION_ROW_CLASS,
    conditionValueOptions,
    getEventDescription,
    OPERATOR_OPTIONS,
    SCENARIO_INDEX_CLASS,
    SCENARIO_SHELL_CLASS,
    SCENARIO_STEP_CLASS,
    STEP_BADGE_CLASS,
} from '../_lib/operational-triggers-ui';
import { ActionEditor } from './ActionEditor';

const PUBLISH_STATE_LABEL: Record<ScenarioPublishState, string> = {
    synced: 'Publicado',
    dirty: 'Rascunho',
    new: 'Novo',
};

interface ScenarioEditorProps {
    index: number;
    scenario: OperationalTriggerScenario;
    eventOptions: Array<{ value: string; label: string }>;
    actionTypeOptions: Array<{ value: string; label: string }>;
    conditionFields: OperationalTriggerMetadata['condition_fields'];
    publishState: ScenarioPublishState;
    isPublishing: boolean;
    onPublish: () => void;
    onChange: (next: OperationalTriggerScenario) => void;
    onRemove: () => void;
}

export function ScenarioEditor({
    index,
    scenario,
    eventOptions,
    actionTypeOptions,
    conditionFields,
    publishState,
    isPublishing,
    onPublish,
    onChange,
    onRemove,
}: ScenarioEditorProps) {
    const fields = conditionFields[scenario.event] ?? {};
    const fieldOptions = Object.entries(fields).map(([value, cfg]) => ({
        value,
        label: cfg.label ?? value,
    }));
    const eventSample = useMemo(() => buildScenarioSampleEvent(scenario), [scenario]);
    const canPublish = publishState !== 'synced';

    return (
        <article className={SCENARIO_SHELL_CLASS} aria-label={`Cenário ${scenario.name}`}>
            <header className="flex flex-wrap items-center gap-3 border-b border-border px-4 py-4 md:px-5">
                <span className={SCENARIO_INDEX_CLASS} aria-hidden>
                    {String(index + 1).padStart(2, '0')}
                </span>
                <div className="min-w-0 flex-1 space-y-1">
                    <Label htmlFor={`scenario-name-${scenario.id}`} className={TYPOGRAPHY.hint}>
                        Nome do gatilho
                    </Label>
                    <Input
                        id={`scenario-name-${scenario.id}`}
                        value={scenario.name}
                        onChange={(e) => onChange({ ...scenario, name: e.target.value })}
                        className="h-9 max-w-lg font-semibold"
                    />
                </div>
                <div className="flex flex-wrap items-center gap-2">
                    <span
                        className="rounded-full px-2.5 py-1 text-xs font-semibold"
                        style={
                            publishState === 'synced'
                                ? { background: withAlpha(COLORS.brand, 0.12), color: COLORS.brand }
                                : { background: withAlpha(COLORS.warning, 0.12), color: COLORS.warning }
                        }
                    >
                        {PUBLISH_STATE_LABEL[publishState]}
                    </span>
                    <div className="flex items-center gap-2">
                        <Switch
                            id={`enabled-${scenario.id}`}
                            checked={scenario.enabled}
                            onCheckedChange={(enabled) => onChange({ ...scenario, enabled })}
                        />
                        <Label htmlFor={`enabled-${scenario.id}`} className={TYPOGRAPHY.hint}>
                            {scenario.enabled ? 'Ativo' : 'Inativo'}
                        </Label>
                    </div>
                    <Button
                        type="button"
                        variant={canPublish ? 'default' : 'outline'}
                        size="sm"
                        onClick={onPublish}
                        disabled={!canPublish || isPublishing}
                    >
                        {isPublishing ? (
                            <Loader2 className="mr-2 size-4 animate-spin" aria-hidden />
                        ) : (
                            <Save className="mr-2 size-4" aria-hidden />
                        )}
                        Publicar
                    </Button>
                    <Button type="button" variant="ghost" size="icon" onClick={onRemove} aria-label="Remover cenário">
                        <Trash2 className="size-4" aria-hidden />
                    </Button>
                </div>
            </header>

            <section className={SCENARIO_STEP_CLASS}>
                <div className="mb-2 flex items-center gap-2">
                    <span className={STEP_BADGE_CLASS}>1 · Quando</span>
                    <Zap className="size-3.5 text-muted-foreground" aria-hidden />
                </div>
                <Label htmlFor={`event-${scenario.id}`}>O que acontece no sistema?</Label>
                <ProductSelect
                    id={`event-${scenario.id}`}
                    fullWidth
                    value={scenario.event}
                    onChange={(event) =>
                        onChange({
                            ...scenario,
                            event: event as OperationalTriggerScenario['event'],
                            conditions: [],
                        })
                    }
                    options={eventOptions}
                    placeholder="Escolha o evento"
                />
                <p className={cn(TYPOGRAPHY.hint, 'text-muted-foreground')}>
                    {getEventDescription(scenario.event)}
                </p>
            </section>

            <section className={SCENARIO_STEP_CLASS}>
                <div className="mb-2 flex items-center gap-2">
                    <span className={STEP_BADGE_CLASS}>2 · Se (opcional)</span>
                    <Filter className="size-3.5 text-muted-foreground" aria-hidden />
                </div>
                <p className={cn('mb-3', TYPOGRAPHY.hint, 'text-muted-foreground')}>
                    Filtros extras. Deixe vazio para disparar em todo evento do tipo escolhido.
                </p>

                {scenario.conditions.length === 0 ? (
                    <p
                        className="rounded-lg border border-dashed px-4 py-3 text-sm text-muted-foreground"
                        style={{ borderColor: COLORS.line }}
                    >
                        Sem filtros — qualquer ocorrência do evento acima pode disparar as ações.
                    </p>
                ) : (
                    <div className="space-y-2">
                        {scenario.conditions.map((condition, conditionIndex) => {
                            const fieldCfg = fields[condition.field];
                            const valueOptions = conditionValueOptions(fieldCfg);

                            return (
                            <div key={condition.id} className={CONDITION_ROW_CLASS}>
                                <ProductSelect
                                    fullWidth
                                    value={condition.field}
                                    onChange={(field) => {
                                        const next = [...scenario.conditions];
                                        next[conditionIndex] = { ...condition, field, value: '' };
                                        onChange({ ...scenario, conditions: next });
                                    }}
                                    options={fieldOptions}
                                    placeholder="Campo"
                                    aria-label="Campo do filtro"
                                />
                                <ProductSelect
                                    fullWidth
                                    value={condition.operator}
                                    onChange={(operator) => {
                                        const next = [...scenario.conditions];
                                        next[conditionIndex] = { ...condition, operator };
                                        onChange({ ...scenario, conditions: next });
                                    }}
                                    options={[...OPERATOR_OPTIONS]}
                                    aria-label="Operador do filtro"
                                />
                                {valueOptions.length > 0 ? (
                                    <ProductSelect
                                        fullWidth
                                        value={condition.value}
                                        onChange={(value) => {
                                            const next = [...scenario.conditions];
                                            next[conditionIndex] = { ...condition, value };
                                            onChange({ ...scenario, conditions: next });
                                        }}
                                        options={valueOptions}
                                        placeholder="Escolha o status"
                                        aria-label="Valor do filtro"
                                    />
                                ) : (
                                    <Input
                                        value={condition.value}
                                        placeholder="Valor"
                                        onChange={(e) => {
                                            const next = [...scenario.conditions];
                                            next[conditionIndex] = { ...condition, value: e.target.value };
                                            onChange({ ...scenario, conditions: next });
                                        }}
                                    />
                                )}
                                <Button
                                    type="button"
                                    variant="ghost"
                                    size="sm"
                                    onClick={() =>
                                        onChange({
                                            ...scenario,
                                            conditions: scenario.conditions.filter((c) => c.id !== condition.id),
                                        })
                                    }
                                >
                                    Remover
                                </Button>
                            </div>
                            );
                        })}
                    </div>
                )}

                <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    className="mt-3"
                    onClick={() => onChange({ ...scenario, conditions: [...scenario.conditions, newCondition()] })}
                >
                    <Plus className="mr-2 size-4" aria-hidden />
                    Adicionar filtro
                </Button>
            </section>

            <section className={SCENARIO_STEP_CLASS}>
                <div className="mb-2 flex items-center gap-2">
                    <span className={STEP_BADGE_CLASS}>3 · Então</span>
                    <ArrowRight className="size-3.5 text-muted-foreground" aria-hidden />
                </div>
                <p className={cn('mb-3', TYPOGRAPHY.hint, 'text-muted-foreground')}>
                    O que o sistema deve fazer automaticamente quando o gatilho casar.
                </p>

                {scenario.actions.length === 0 ? (
                    <p
                        className="mb-3 rounded-lg border border-dashed px-4 py-3 text-sm"
                        style={{
                            borderColor: withAlpha(COLORS.warning, 0.35),
                            background: withAlpha(COLORS.warning, 0.06),
                            color: COLORS.warning,
                        }}
                    >
                        Nenhuma ação configurada. Adicione pelo menos uma notificação ou tarefa.
                    </p>
                ) : (
                    <div className="space-y-3">
                        {scenario.actions.map((action, actionIndex) => (
                            <ActionEditor
                                key={action.id}
                                action={action}
                                index={actionIndex}
                                eventSample={eventSample}
                                onChange={(next) => {
                                    const actions = [...scenario.actions];
                                    actions[actionIndex] = next;
                                    onChange({ ...scenario, actions });
                                }}
                                onRemove={() =>
                                    onChange({
                                        ...scenario,
                                        actions: scenario.actions.filter((a) => a.id !== action.id),
                                    })
                                }
                            />
                        ))}
                    </div>
                )}

                <div className="mt-4 flex flex-wrap gap-2">
                    {actionTypeOptions.map((option) => (
                        <Button
                            key={option.value}
                            type="button"
                            variant="outline"
                            size="sm"
                            onClick={() =>
                                onChange({
                                    ...scenario,
                                    actions: [
                                        ...scenario.actions,
                                        newAction(option.value as OperationalActionType),
                                    ],
                                })
                            }
                        >
                            <Plus className="mr-1.5 size-3.5" aria-hidden />
                            {option.label}
                        </Button>
                    ))}
                </div>
            </section>
        </article>
    );
}

