'use client';

import { AlertTriangle, ChevronDown, Download, FlaskConical, History, Plus, Save, Upload } from 'lucide-react';
import { useEffect, useMemo, useRef, useState } from 'react';

import { Button } from '@/components/ui/button';
import {
    Collapsible,
    CollapsibleContent,
    CollapsibleTrigger,
} from '@/components/ui/collapsible';
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import {
    COLORS,
    OperationalLoadingPanel,
    ProductInlineHint,
    TYPOGRAPHY,
    withAlpha,
} from '@/design-system';
import {
    buildConfigWithPublishedScenario,
    exportConfig,
    getScenarioPublishState,
    importConfig,
    isConfigDirty,
    newScenario,
    summarizeImport,
} from '@/functions/operational-triggers/schema';
import {
    useOperationalTriggersConfigQuery,
    useOperationalTriggersExecutionsQuery,
    useOperationalTriggersMetadataQuery,
    useSaveOperationalTriggersConfigMutation,
} from '@/hooks/queries/operational-triggers';
import { OperationalTriggersService } from '@/services/operational-triggers';
import type { OperationalTriggerConfig } from '@/types/operational-triggers';
import { OPERATIONAL_TRIGGER_EXECUTIONS_PANEL_LIMIT, SCHEMA_VERSION } from '@/types/operational-triggers';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { cn } from '@/lib/utils';

import { getConfiguracoesPanelStyle } from '../../_lib/configuracoes-shared';
import { actionSelectOptions, eventSelectOptions } from '../_lib/operational-triggers-ui';
import { OperationalTriggersMetricsCard } from './OperationalTriggersMetricsCard';
import { ScenarioEditor } from './ScenarioEditor';

export function OperationalTriggersPanel() {
    const fileInputRef = useRef<HTMLInputElement>(null);
    const { data: configData, isLoading } = useOperationalTriggersConfigQuery();
    const { data: metadata } = useOperationalTriggersMetadataQuery();
    const { data: executionsData } = useOperationalTriggersExecutionsQuery(
        OPERATIONAL_TRIGGER_EXECUTIONS_PANEL_LIMIT,
    );
    const { mutate: saveConfig, isPending: isSaving } = useSaveOperationalTriggersConfigMutation();
    const [draft, setDraft] = useState<OperationalTriggerConfig | null>(null);
    const [published, setPublished] = useState<OperationalTriggerConfig | null>(null);
    const [importSummary, setImportSummary] = useState<ReturnType<typeof summarizeImport> | null>(null);
    const [pendingImport, setPendingImport] = useState<OperationalTriggerConfig | null>(null);
    const [publishingScenarioId, setPublishingScenarioId] = useState<string | null>(null);

    useEffect(() => {
        if (configData) {
            const normalized = {
                version: configData.version ?? SCHEMA_VERSION,
                scenarios: configData.scenarios ?? [],
                is_active: configData.is_active ?? true,
            };
            setDraft(normalized);
            setPublished(normalized);
        }
    }, [configData]);

    const eventOptions = useMemo(
        () => eventSelectOptions(metadata?.events ?? []),
        [metadata?.events],
    );
    const actionTypeOptions = useMemo(
        () => actionSelectOptions(metadata?.actions ?? []),
        [metadata?.actions],
    );
    const conditionFields = metadata?.condition_fields ?? {};
    const hasDraftChanges = draft && published ? isConfigDirty(draft, published) : false;

    const handleSave = () => {
        if (!draft) return;
        saveConfig(draft, {
            onSuccess: () => {
                setPublished(draft);
                sendToastMessage({ type: 'success', title: 'Gatilhos operacionais publicados' });
            },
            onError: () => sendToastMessage({ type: 'error', title: 'Erro ao salvar gatilhos' }),
        });
    };

    const handlePublishScenario = (scenarioId: string) => {
        if (!draft) return;
        const scenario = draft.scenarios.find((item) => item.id === scenarioId);
        const payload = buildConfigWithPublishedScenario(draft, published ?? draft, scenarioId);

        setPublishingScenarioId(scenarioId);
        saveConfig(payload, {
            onSuccess: () => {
                setPublished(payload);
                setPublishingScenarioId(null);
                sendToastMessage({
                    type: 'success',
                    title: 'Gatilho publicado',
                    description: scenario?.name ?? 'Cenário atualizado no servidor.',
                });
            },
            onError: () => {
                setPublishingScenarioId(null);
                sendToastMessage({ type: 'error', title: 'Erro ao publicar gatilho' });
            },
        });
    };

    const handleDryRun = async () => {
        try {
            const result = await OperationalTriggersService.dryRun({
                event_id: 'dry-run:preview',
                event_type: 'due.liquidacao_ready',
                host: 'celer',
                credor: 'Maria Silva',
                npu: '0001234-56.2024.8.26.0100',
                extrato_id: '00000000-0000-0000-0000-000000000001',
            });
            const matched = (result.matched_scenarios as unknown[])?.length ?? 0;
            sendToastMessage({
                type: 'success',
                title: 'Simulação concluída',
                description: `${matched} gatilho(s) seriam disparados com o evento de exemplo.`,
            });
        } catch {
            sendToastMessage({ type: 'error', title: 'Falha na simulação' });
        }
    };

    const handleExport = () => {
        if (!draft) return;
        const blob = new Blob([JSON.stringify(exportConfig(draft), null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const anchor = document.createElement('a');
        anchor.href = url;
        anchor.download = 'gatilhos-operacionais.json';
        anchor.click();
        URL.revokeObjectURL(url);
    };

    const handleImportFile = (file: File) => {
        const reader = new FileReader();
        reader.onload = () => {
            try {
                const imported = importConfig(reader.result);
                setPendingImport(imported);
                setImportSummary(summarizeImport(imported));
            } catch {
                sendToastMessage({ type: 'error', title: 'Arquivo JSON inválido' });
            }
        };
        reader.readAsText(file);
    };

    if (isLoading || !draft) {
        return <OperationalLoadingPanel message="Carregando gatilhos operacionais..." minHeight="320px" />;
    }

    return (
        <div className="space-y-6">
            <ProductInlineHint
                icon={AlertTriangle}
                accentColor={COLORS.warning}
                title="Automações com efeito real"
                description="Cada gatilho segue a lógica Quando → Se (opcional) → Então. Publique por card ou tudo de uma vez."
            />

            <div
                className="flex flex-wrap items-center gap-3 rounded-xl border px-4 py-3"
                style={getConfiguracoesPanelStyle()}
            >
                <div className="flex items-center gap-2">
                    <Switch
                        id="config-active"
                        checked={draft.is_active ?? true}
                        onCheckedChange={(is_active) => setDraft({ ...draft, is_active })}
                    />
                    <Label htmlFor="config-active">Motor ativo</Label>
                </div>
                {hasDraftChanges ? (
                    <span
                        className="rounded-full px-2.5 py-1 text-xs font-semibold"
                        style={{ background: withAlpha(COLORS.warning, 0.12), color: COLORS.warning }}
                    >
                        Alterações não publicadas
                    </span>
                ) : (
                    <span
                        className="rounded-full px-2.5 py-1 text-xs font-semibold"
                        style={{ background: withAlpha(COLORS.brand, 0.12), color: COLORS.brand }}
                    >
                        Publicado
                    </span>
                )}
                <div className="ml-auto flex flex-wrap gap-2">
                    <Button type="button" variant="outline" size="sm" onClick={() => void handleDryRun()}>
                        <FlaskConical className="mr-2 size-4" aria-hidden />
                        Simular
                    </Button>
                    <Button type="button" variant="outline" size="sm" onClick={() => fileInputRef.current?.click()}>
                        <Upload className="mr-2 size-4" aria-hidden />
                        Importar
                    </Button>
                    <Button type="button" variant="outline" size="sm" onClick={handleExport}>
                        <Download className="mr-2 size-4" aria-hidden />
                        Exportar
                    </Button>
                    <Button type="button" size="sm" onClick={handleSave} disabled={isSaving || !hasDraftChanges}>
                        <Save className="mr-2 size-4" aria-hidden />
                        Publicar tudo
                    </Button>
                </div>
            </div>

            <input
                ref={fileInputRef}
                type="file"
                accept="application/json"
                className="hidden"
                onChange={(event) => {
                    const file = event.target.files?.[0];
                    if (file) handleImportFile(file);
                    event.target.value = '';
                }}
            />

            <Dialog
                open={pendingImport !== null}
                onOpenChange={(open) => {
                    if (!open) {
                        setPendingImport(null);
                        setImportSummary(null);
                    }
                }}
            >
                <DialogContent className="max-w-md rounded-2xl">
                    <DialogHeader>
                        <DialogTitle>Importar configuração?</DialogTitle>
                        <DialogDescription>
                            {importSummary
                                ? `${importSummary.totalScenarios} gatilho(s), ${importSummary.enabledScenarios} ativo(s), ${importSummary.notifyActions} notificação(ões).`
                                : 'Revise o resumo antes de aplicar.'}
                        </DialogDescription>
                    </DialogHeader>
                    <DialogFooter>
                        <Button
                            type="button"
                            variant="outline"
                            onClick={() => {
                                setPendingImport(null);
                                setImportSummary(null);
                            }}
                        >
                            Cancelar
                        </Button>
                        <Button
                            type="button"
                            onClick={() => {
                                if (pendingImport) setDraft(pendingImport);
                                setPendingImport(null);
                                setImportSummary(null);
                                sendToastMessage({ type: 'success', title: 'Importado no rascunho local' });
                            }}
                        >
                            Aplicar no rascunho
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            <div className="flex items-center justify-between gap-3">
                <div>
                    <p className={cn('font-semibold', TYPOGRAPHY.title)}>Gatilhos configurados</p>
                    <p className={cn(TYPOGRAPHY.hint, 'text-muted-foreground')}>
                        {draft.scenarios.length} regra(s) · edite na ordem Quando → Se → Então
                    </p>
                </div>
                <Button
                    type="button"
                    variant="outline"
                    onClick={() =>
                        setDraft({
                            ...draft,
                            scenarios: [...draft.scenarios, newScenario(draft.scenarios.length + 1)],
                        })
                    }
                >
                    <Plus className="mr-2 size-4" aria-hidden />
                    Novo gatilho
                </Button>
            </div>

            <div className="space-y-5">
                {draft.scenarios.map((scenario, index) => (
                    <ScenarioEditor
                        key={scenario.id}
                        index={index}
                        scenario={scenario}
                        eventOptions={eventOptions}
                        actionTypeOptions={actionTypeOptions}
                        conditionFields={conditionFields}
                        publishState={getScenarioPublishState(scenario, published)}
                        isPublishing={publishingScenarioId === scenario.id}
                        onPublish={() => handlePublishScenario(scenario.id)}
                        onChange={(next) => {
                            const scenarios = [...draft.scenarios];
                            scenarios[index] = next;
                            setDraft({ ...draft, scenarios });
                        }}
                        onRemove={() =>
                            setDraft({
                                ...draft,
                                scenarios: draft.scenarios.filter((s) => s.id !== scenario.id),
                            })
                        }
                    />
                ))}
            </div>

            <Collapsible>
                <CollapsibleTrigger asChild>
                    <Button type="button" variant="ghost" className="w-full justify-between rounded-xl border px-4">
                        <span className={cn('font-semibold', TYPOGRAPHY.body)}>Monitoramento e falhas</span>
                        <ChevronDown className="size-4" aria-hidden />
                    </Button>
                </CollapsibleTrigger>
                <CollapsibleContent className="pt-4">
                    <OperationalTriggersMetricsCard />
                </CollapsibleContent>
            </Collapsible>

            <Collapsible>
                <CollapsibleTrigger asChild>
                    <Button type="button" variant="ghost" className="w-full justify-between rounded-xl border px-4">
                        <span className="flex items-center gap-2">
                            <History className="size-4" style={{ color: COLORS.brand }} aria-hidden />
                            <span className={cn('font-semibold', TYPOGRAPHY.body)}>Histórico de execuções</span>
                        </span>
                        <ChevronDown className="size-4" aria-hidden />
                    </Button>
                </CollapsibleTrigger>
                <CollapsibleContent className="pt-4">
                    <div className="rounded-xl border p-4" style={getConfiguracoesPanelStyle()}>
                        {(executionsData?.results ?? []).length === 0 ? (
                            <p className={cn(TYPOGRAPHY.hint, 'text-muted-foreground')}>
                                Nenhuma execução registrada ainda.
                            </p>
                        ) : (
                            <ul className="space-y-2">
                                {(executionsData?.results ?? []).map((row) => (
                                    <li
                                        key={row.id}
                                        className="flex flex-wrap items-center justify-between gap-2 rounded-lg border px-3 py-2 text-sm"
                                        style={{ borderColor: COLORS.line }}
                                    >
                                        <span>
                                            {row.event_type} · {row.scenario_id}
                                        </span>
                                        <span
                                            className={cn(
                                                'text-xs',
                                                row.status === 'error' ? 'text-red-600' : 'text-muted-foreground',
                                            )}
                                        >
                                            {row.status}
                                        </span>
                                    </li>
                                ))}
                            </ul>
                        )}
                    </div>
                </CollapsibleContent>
            </Collapsible>
        </div>
    );
}

