1	import { normalizeDeducoesOutput, normalizeIrOutput, uid } from '@/functions/calculator-triggers/schema';
2	import type { TriggerScenario } from '@/types/calculator-triggers';
3	
4	export function normalizeScenarioFromServer(scenario: TriggerScenario): TriggerScenario {
5	    return {
6	        ...scenario,
7	        outputs: (scenario.outputs ?? []).map((output) =>
8	            output.field === 'outrasDeducoes'
9	                ? { ...output, value: normalizeDeducoesOutput(output.value) }
10	                : output.field === 'incideIR'
11	                  ? { ...output, value: normalizeIrOutput(output.value) }
12	                  : output,
13	        ),
14	    };
15	}
16	
17	export function normalizeScenariosFromServer(scenarios: TriggerScenario[]): TriggerScenario[] {
18	    return (scenarios ?? []).map(normalizeScenarioFromServer);
19	}
20	
21	function scenarioSnapshotForCompare(scenario: TriggerScenario): string {
22	    return JSON.stringify({ ...scenario, audit: undefined });
23	}
24	
25	export function isScenarioDirty(local: TriggerScenario, saved: TriggerScenario | undefined): boolean {
26	    if (!saved) return true;
27	    return scenarioSnapshotForCompare(local) !== scenarioSnapshotForCompare(saved);
28	}
29	
30	/** Full local list order; only the target scenario is taken from local edits. */
31	export function buildMergedScenariosForSave(
32	    localScenarios: TriggerScenario[],
33	    savedScenarios: TriggerScenario[],
34	    targetScenarioId: string,
35	): TriggerScenario[] {
36	    const savedById = new Map(savedScenarios.map((scenario) => [scenario.id, scenario]));
37	
38	    return localScenarios.map((local) => {
39	        if (local.id === targetScenarioId) return local;
40	        return savedById.get(local.id) ?? local;
41	    });
42	}
43	
44	export function wasScenarioPersisted(scenarioId: string, savedScenarios: TriggerScenario[]): boolean {
45	    return savedScenarios.some((scenario) => scenario.id === scenarioId);
46	}
47	
48	/** Clones a scenario with fresh ids; audit is cleared (new scenario). */
49	export function duplicateScenario(scenario: TriggerScenario, index: number): TriggerScenario {
50	    const baseName = scenario.name?.trim() || `Cenário ${index + 1}`;
51	
52	    return {
53	        ...scenario,
54	        id: uid(),
55	        name: `${baseName} (cópia)`,
56	        audit: undefined,
57	        conditions: (scenario.conditions ?? []).map((condition) => ({
58	            ...condition,
59	            id: uid(),
60	        })),
61	        outputs: (scenario.outputs ?? []).map((output) => ({
62	            ...output,
63	            id: uid(),
64	        })),
65	    };
66	}
